// Final report summary
const reportData = $('Generate HTML Report').item.json;
const savedReport = $('Save Report to Supabase').item.json;

const summary = {
  reportId: reportData.metadata.id,
  title: reportData.metadata.title,
  period: reportData.metadata.period,
  generatedAt: reportData.metadata.generatedAt,
  savedToDatabase: !!savedReport.data,
  metricsAnalyzed: reportData.metadata.summary.totalMetrics,
  competitorsAnalyzed: reportData.metadata.summary.totalCompetitors,
  keywordsAnalyzed: reportData.metadata.summary.totalKeywords,
  reportLength: reportData.htmlReport.length,
  analysisCompleted: true
};

return summary;
